.apps-page .apps-heading{justify-content:space-between;margin-bottom:22px;flex-wrap:wrap;gap:20px}
.apps-toolbar{display:flex;align-items:center;gap:8px;max-width:100%;margin-top:2px}
.apps-search{width:238px;max-width:100%;min-width:0}
.apps-tabs{display:flex;gap:6px;margin:0 0 24px}.apps-tabs a{font-size:13px;padding:8px 16px;border-radius:999px;text-decoration:none;color:var(--muted-foreground)}.apps-tabs a[aria-current=page]{background:var(--muted);color:var(--foreground);font-weight:500}
.apps-filter{display:flex;align-items:center;gap:8px;margin:0 0 24px;max-width:100%}.apps-filter>.control-select{min-width:0}.apps-filter button{flex-shrink:0}
.apps-notice{color:var(--muted-foreground);font-size:var(--text-meta);line-height:1.6;margin:0 0 22px;max-width:640px}.apps-notice a{color:var(--foreground);text-underline-offset:3px}
.apps-group{margin:0 0 36px}.apps-group-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:14px}.apps-group-heading .text-link{display:inline-flex;align-items:center;gap:6px;flex-shrink:0;font-size:var(--text-meta)}.apps-group h2{font-size:var(--text-section);font-weight:600;margin:0}
.apps-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 32px}
.app-tile{display:flex;align-items:center;gap:8px;min-width:0;min-height:58px;border-radius:12px;padding:6px 0}
.app-tile:hover{background:var(--hover)}.app-summary{display:flex;align-items:center;gap:12px;min-width:0;flex:1;text-decoration:none;color:inherit;padding:4px;border-radius:10px}
.app-copy{display:flex;flex-direction:column;min-width:0;gap:3px}.app-copy strong{font-size:14px;font-weight:500;line-height:1.4}.app-copy>span{color:var(--muted-foreground);font-size:13px;line-height:1.5;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}
.app-logo{position:relative;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:36px;height:36px;border:1px solid var(--border);border-radius:9px;background:#fff;overflow:hidden;color:#363636}
.app-logo img{display:block;width:26px;height:26px;object-fit:contain}.app-logo>span{display:none;font-size:16px;font-weight:600}.app-logo:has(img[data-logo-failed])>span{display:block}.app-logo img[data-logo-failed]{display:none}
.apps-sidebar-heading{margin-top:28px}.apps-connections a{gap:10px;font-size:13px}.apps-connections .app-logo{width:20px;height:20px;border:0;border-radius:4px}.apps-connections .app-logo img{width:18px;height:18px}.apps-connections .app-logo>span{font-size:12px}.apps-connections a>span:not(.app-logo){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.app-pending-dot{width:5px;height:5px;border-radius:50%;background:var(--muted-foreground);margin-left:auto;flex-shrink:0}
.apps-empty{font-size:14px;color:var(--muted-foreground);padding:28px 0}
.apps-dialog{width:540px;padding:32px}.apps-dialog-close{position:absolute;right:12px;top:12px}
.app-detail{min-width:0;overflow-wrap:anywhere}
.app-detail header{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin:0 28px 24px 0}.app-detail header .app-logo{width:56px;height:56px;border-radius:13px}.app-detail header .app-logo img{width:42px;height:42px}
.app-detail h2{font-size:22px;font-weight:600;margin:0 0 5px}.app-detail header p{font-size:13px;line-height:1.5;color:var(--muted-foreground);margin:0}.app-detail h3{font-size:var(--text-section);font-weight:600;margin:26px 0 8px}.app-detail .feedback{font-size:13px;line-height:1.6}
.app-account{padding:16px 0;border-bottom:1px solid var(--border)}.app-account:last-child{border-bottom:0}.app-account strong{font-size:14px;font-weight:500}.app-account-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.app-account [data-app-authorization]{margin-top:12px}.app-detail .muted{font-size:13px}
.app-add-account{margin-top:18px;padding-top:16px;border-top:1px solid var(--border);font-size:13px}.app-add-account summary{cursor:pointer;font-weight:500}.app-add-account form{display:grid;gap:12px;margin-top:16px}.app-add-account form label{display:grid;gap:8px;font-size:13px}.app-add-account input{width:100%;min-width:0}.app-add-account form>button{justify-self:start}
.app-detail-page{max-width:540px;padding-top:12px}
@media(max-width:1000px){.apps-grid{grid-template-columns:1fr}.apps-toolbar{flex-wrap:wrap}.apps-page .apps-heading{gap:16px}}
@media(max-width:760px){.apps-grid{grid-template-columns:1fr;gap:8px}.apps-toolbar{width:100%;flex-wrap:nowrap}.apps-search{flex:1;width:auto}.apps-group{margin-bottom:30px}.apps-page .apps-heading{margin-bottom:20px}.apps-dialog{padding:24px 20px}.app-add-account input{font-size:16px}}

.app-detail{container-type:inline-size}
@container(max-width:180px){.app-detail header{margin-right:0;padding-top:44px}}

@media(max-width:760px){.apps-tabs a{display:inline-flex;align-items:center;min-height:44px}}

.app-unavailable-action{display:inline-flex;align-items:center;gap:4px}

@media(max-width:760px){.apps-group-heading .text-link{display:inline-flex;align-items:center;min-height:44px}}
